Import-Module ActiveDirectory

# Horario de inicio de sesión: logonHours son 21 bytes (168 h de la semana) y se guardan en UTC
function Set-Horario($sam, [int[]]$dias, [int]$inicio, [int]$horas) {
    $bytes  = New-Object byte[] 21
    $offset = [int][TimeZoneInfo]::Local.GetUtcOffset((Get-Date)).TotalHours
    foreach ($d in $dias) {
        for ($h = $inicio; $h -lt $inicio + $horas; $h++) {
            $utc = ($d * 24 + $h - $offset) % 168
            if ($utc -lt 0) { $utc += 168 }
            $bytes[[math]::Floor($utc / 8)] = $bytes[[math]::Floor($utc / 8)] -bor (1 -shl ($utc % 8))
        }
    }
    Set-ADUser $sam -Replace @{logonHours = [byte[]]$bytes}
}

