    @{OU="Admin";       G="G_Admin";       P="adm"; PC="PC-ADM"; Dias=1..5; Ini=9; H=8},
    @{OU="Logistica";   G="G_Logistica";   P="log"; PC="PC-LOG"; Dias=1..6; Ini=8; H=7},
    @{OU="Mantencion";  G="G_Mantencion";  P="man"; PC="PC-MAN"; Dias=0..6; Ini=8; H=6}
)

foreach ($a in $areas) {
    New-ADOrganizationalUnit -Name $a.OU -Path $raiz
    $ou = "OU=$($a.OU),$raiz"
    New-ADGroup -Name $a.G -GroupScope Global -GroupCategory Security -Path $ou
    foreach ($n in 1..2) {
        $sam = "$($a.P).usuario$n"
        New-ADUser -Name "Usuario$n $($a.OU)" -GivenName "Usuario$n" -Surname $a.OU `
            -SamAccountName $sam -UserPrincipalName "$sam@$dominio" -Path $ou `
            -AccountPassword $pass -Enabled $true -PasswordNeverExpires $true `
            -LogonWorkstations ("{0}0{1}" -f $a.PC, $n)
        Add-ADGroupMember -Identity $a.G -Members $sam
        Set-Horario $sam $a.Dias $a.Ini $a.H
    }
}

